def choose_move(observation):
    x, y = observation['self_position']
    width, height = observation['grid_width'], observation['grid_height']
    resources = observation['resources'] or []
    obstacles = set(observation['obstacles'] or [])
    opponent_x, opponent_y = observation['opponent_position']

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    near_res = min(((res['position'], dist([x, y], res['position'])) for res in resources), key=lambda v: v[1], default=(None, float('inf')))[0]
    near_opp = (opponent_x, opponent_y)

    def move_towards(target):
        dx = dy = 0
        if target:
            if target[0] > x:
                dx = 1
            elif target[0] < x:
                dx = -1
            if target[1] > y:
                dy = 1
            elif target[1] < y:
                dy = -1
        return dx, dy

    def valid(pos):
        nx, ny = pos
        return 0 <= nx < width and 0 <= ny < height and pos not in obstacles

    directions = [(-1,0),(1,0),(0,-1),(0,1)]
    target = near_res or near_opp
    dx, dy = move_towards(target)
    if (dx, dy) != (0,0):
        new_pos = [x+dx, y+dy]
        if valid(new_pos):
            return [dx, dy]
    for dx, dy in directions:
        new_pos = [x+dx, y+dy]
        if valid(new_pos):
            return [dx, dy]
    return [0, 0]
